package com.mantou.salesdialer.contacts;
import android.content.Context;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;
import java.time.*;import java.util.*;import java.util.concurrent.*;
import com.mantou.salesdialer.contacts.PhoneIntakeModel.*;
final class LocalPlanStoreChecks {
 private final Context context;private int checks;private static final long NOW=Instant.parse("2026-10-19T01:00:00Z").toEpochMilli(),DUE=NOW+60000;
 private static final Clock CLOCK=Clock.fixed(Instant.ofEpochMilli(NOW),ZoneOffset.UTC);
 private LocalPlanStoreChecks(Context c){context=c;}static int run(Context c)throws Exception{var t=new LocalPlanStoreChecks(c);t.run();return t.checks;}
 private String name(){return "phone-fixture-"+UUID.randomUUID().toString().replace("-","")+".db";}
 private PhoneIntakeStore open(String n){return PhoneIntakeStore.fixture(context,n,CLOCK,p->{});}
 private void check(boolean v){checks++;if(!v)throw new IllegalStateException("LOCAL_PLAN_ASSERTION_"+checks);}
 private void denied(Runnable r,String code){checks++;try{r.run();}catch(RuntimeException e){if(code.equals(e.getMessage()))return;throw new IllegalStateException("UNEXPECTED_PLAN_ERROR",e);}throw new IllegalStateException("EXPECTED_"+code);}
 private SQLiteDatabase raw(String n){return SQLiteDatabase.openDatabase(context.getDatabasePath(n).getAbsolutePath(),null,SQLiteDatabase.OPEN_READWRITE);}
 private String add(PhoneIntakeStore s){String id=s.importRows(List.of("19900000201"),"GENERATED_PLAN_FIXTURE",Qualification.CONFIRMED).rows.get(0).targetId;s.createDraft(id,1);return id;}
 private void run()throws Exception{
  String n=name(),target;try(PhoneIntakeStore s=open(n)){target=add(s);check(s.plan().plan.paused&&s.plan().plan.version==0);s.arrangeDraft(target,0,1,1,DUE);check(s.plan().plan.version==1&&s.plan().status.equals("NOT_DUE")&&s.planEvents()==1);denied(()->s.arrangeDraft(target,0,1,1,DUE),"STALE_PLAN");denied(()->s.arrangeDraft(target,1,1,1,NOW-1),"PAST_DUE");denied(()->s.arrangeDraft(target,1,1,1,Instant.parse("2026-10-24T01:00:00Z").toEpochMilli()),"OUTSIDE_WINDOW");check(s.planEvents()==1);s.qualify(target,1,Qualification.CONFIRMED,"GENERATED");check(s.plan().status.equals("STALE_CONTACT"));denied(()->s.arrangeDraft(target,1,2,1,DUE),"STALE_CONTACT");s.refreshDraft(target,2,1);s.arrangeDraft(target,1,2,2,DUE);check(s.plan().plan.version==2&&s.plan().plan.contactRevision==2);}
  try(PhoneIntakeStore s=open(n)){check(s.plan().plan.version==2&&!s.plan().plan.paused);s.recoverPlan();check(s.plan().plan.version==3&&s.plan().plan.paused);s.recoverPlan();s.pausePlan(3);check(s.planEvents()==3);denied(()->s.pausePlan(2),"STALE_PLAN");s.arrangeDraft(target,3,2,2,DUE);s.refuse(target,2);check(s.plan().status.equals("STALE_CONTACT"));denied(()->s.arrangeDraft(target,4,3,2,DUE),"STALE_CONTACT");s.pausePlan(4);check(s.plan().plan.paused&&s.plan().plan.version==5);}
  try(PhoneIntakeStore s=PhoneIntakeStore.fixture(context,n,Clock.fixed(Instant.ofEpochMilli(DUE+30001),ZoneOffset.UTC),p->{})){check(s.plan().plan.paused);}
  for(String point:List.of("AFTER_PLAN_WRITE","AFTER_PLAN_EVENT")){String f=name(),id;try(PhoneIntakeStore s=open(f)){id=add(s);}try(PhoneIntakeStore s=PhoneIntakeStore.fixture(context,f,CLOCK,p->{if(p.equals(point))throw new IllegalStateException("PLAN_WRITE_FAILED");})){denied(()->s.arrangeDraft(id,0,1,1,DUE),"PLAN_WRITE_FAILED");}try(PhoneIntakeStore s=open(f)){check(s.plan().plan.version==0&&s.planEvents()==0);s.arrangeDraft(id,0,1,1,DUE);}try(PhoneIntakeStore s=PhoneIntakeStore.fixture(context,f,CLOCK,p->{if(p.equals(point))throw new IllegalStateException("PLAN_WRITE_FAILED");})){denied(()->s.recoverPlan(),"PLAN_WRITE_FAILED");}try(PhoneIntakeStore s=open(f)){check(s.plan().plan.version==1&&!s.plan().plan.paused&&s.planEvents()==1);}}
  String race=name();try(PhoneIntakeStore left=open(race)){String id=add(left);try(PhoneIntakeStore right=open(race)){var threads=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{Callable<String> a=()->{start.await();try{left.arrangeDraft(id,0,1,1,DUE);return "ARRANGED";}catch(IllegalStateException e){return e.getMessage();}};Callable<String> b=()->{start.await();try{right.arrangeDraft(id,0,1,1,DUE);return "ARRANGED";}catch(IllegalStateException e){return e.getMessage();}};var x=threads.submit(a);var y=threads.submit(b);start.countDown();check(new HashSet<>(List.of(x.get(10,TimeUnit.SECONDS),y.get(10,TimeUnit.SECONDS))).equals(Set.of("ARRANGED","STALE_PLAN")));check(left.planEvents()==1);}finally{threads.shutdownNow();}}}
  String expired=name();String expiredTarget;try(PhoneIntakeStore s=open(expired)){expiredTarget=add(s);s.arrangeDraft(expiredTarget,0,1,1,DUE);}try(PhoneIntakeStore s=PhoneIntakeStore.fixture(context,expired,Clock.fixed(Instant.ofEpochMilli(DUE+30001),ZoneOffset.UTC),p->{})){check(s.plan().status.equals("EXPIRED")&&s.planEvents()==1);s.recoverPlan();check(s.plan().plan.paused&&s.plan().plan.version==2);}
  String legacy=name();String oldSlot,draft;try(PhoneIntakeStore s=open(legacy)){String id=add(s);oldSlot=s.slot();draft=s.drafts().get(0).draft.id;}try(SQLiteDatabase db=raw(legacy)){db.execSQL("DROP TABLE phone_cancellations");db.execSQL("DROP TABLE phone_attempt_events");db.execSQL("DROP TABLE phone_attempts");db.execSQL("DROP TABLE phone_plan_events");db.execSQL("DROP TABLE phone_plan");db.execSQL("UPDATE phone_meta SET version=2");db.setVersion(2);}
  denied(()->{try(PhoneIntakeStore ignored=PhoneIntakeStore.fixture(context,legacy,CLOCK,p->{if(p.equals("AFTER_PLAN_SCHEMA"))throw new IllegalStateException("PLAN_MIGRATION_FAILED");})){}},"PLAN_MIGRATION_FAILED");try(SQLiteDatabase db=raw(legacy)){check(db.getVersion()==2);}try(PhoneIntakeStore s=open(legacy)){check(s.slot().equals(oldSlot)&&s.drafts().get(0).draft.id.equals(draft)&&s.draftEvents()==1&&s.plan().plan.version==0);}
  String bad=name();try(PhoneIntakeStore s=open(bad)){String id=add(s);s.arrangeDraft(id,0,1,1,DUE);}try(SQLiteDatabase db=raw(bad)){db.execSQL("DELETE FROM phone_plan_events");}denied(()->{try(PhoneIntakeStore ignored=open(bad)){}},"PHONE_STORE_INVALID");try(SQLiteDatabase db=raw(bad);Cursor c=db.rawQuery("SELECT COUNT(*) FROM phone_plan",null)){check(c.moveToFirst()&&c.getInt(0)==1);}
 }
}
